{ "version": 1, "title": "Class Anatomy", "page": { "width": 1008.0, "height": 612.0, "margin": 36.0, "background": "#ffffff" }, "elements": [ { "type": "label", "id": "title", "x": 48.0, "y": 32.0, "text": "Class Anatomy", "style": { "fill": null, "stroke": null, "stroke_width": null, "dash": null, "opacity": null, "corner_radius": null, "font": null, "font_size": 30.0, "font_weight": 700, "italic": null, "text_color": null, "align": null, "padding": null } }, { "type": "label", "id": "sub", "x": 48.0, "y": 70.0, "text": "Where each part actually lives: fields on the instance, methods on the prototype, statics on the class itself.", "style": { "fill": null, "stroke": null, "stroke_width": null, "dash": null, "opacity": null, "corner_radius": null, "font": null, "font_size": 15.0, "font_weight": null, "italic": null, "text_color": "#6b6a66", "align": null, "padding": null } }, { "type": "shape", "id": "code", "kind": "rect", "x": 48.0, "y": 112.0, "w": 400.0, "h": 300.0, "text": "class Animal {
 static kingdom = 'Animalia';
 #secret = 'hidden';
 constructor(name) { this.name = name; }
 speak() { return this.name + ' makes a sound'; }
 get label() { return this.name.toUpperCase(); }
}

class Dog extends Animal {
 constructor(name, breed) {
 super(name);
 this.breed = breed;
 }
 speak() { return super.speak() + ' (a bark)'; }
